// === Tab: mySketch ===

let particles=[];
let parNum=2000;

function setup() {
  createCanvas(windowWidth, windowHeight);
  for (let i=-1;i<parNum;i++){
    particles.push(new particle(random(width),random(height)));
  }
  background(200)
}

let multMous=1;
let mX=0;
let mY=0;

function draw() {
  mX=(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
  mY=(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));
  for (c=particles.length-1;c>0;c--){
    particles[c].update();
    particles[c].show();
  }
  background(220,220,220,20)
}

function particle(x,y){
  this.pos=createVector(x,y);
  this.oldMove=createVector(0,0);
  this.rand=random(0.95,1.);

  this.update=function (){
    this.move=createVector(mX-this.pos.x,mY-this.pos.y).normalize().div(10*multMous).add(this.oldMove);
    this.oldMove=this.move.div(1.01);
    this.move.add(createVector(random()-0.5,random()-0.5).div(4));
    this.pos.add(this.move);
  }

  this.show=function(){

    strokeWeight(random(6.6,7.));
    point(this.pos.x,this.pos.y);
  }

}

function mousePressed(){
  multMous=-1;
}

function mouseReleased(){
  multMous=1;
}

